
.task-card {
  background: var(--sys-panel);
  border: 1px solid rgba(205, 155, 90, 0.3);
  border-radius: 10px;
  padding: 8px 10px;
  margin-bottom: 6px;
}

.task-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 3px;
}

.task-name {
  font-weight: 700;
  color: var(--sys-gold);
}

.task-state {
  font-size: 11px;
  color: var(--sys-green);
  white-space: nowrap;
}

.task-desc {
  color: var(--sys-text);
  font-size: 13px;
}

.task-progress {
  color: var(--sys-text-dim);
  font-size: 12px;
  margin-top: 2px;
}

.task-reward {
  color: var(--sys-gold);
  font-size: 12px;
  margin-top: 2px;
}
