
.top-panel {
  padding: 10px 14px;
  background: linear-gradient(160deg, rgba(205, 155, 90, 0.16), rgba(20, 16, 9, 0.2));
  border-bottom: 1px solid var(--sys-border);
}

.top-head {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 6px;
}

.top-title {
  font-size: 18px;
  font-weight: 800;
  letter-spacing: 6px;
  color: var(--sys-gold);
  text-shadow: 0 0 12px rgba(230, 192, 122, 0.6);
}

.top-sub {
  font-size: 11px;
  color: var(--sys-text-dim);
  letter-spacing: 2px;
}

.world-row {
  display: flex;
  flex-wrap: wrap;
  gap: 2px 12px;
  margin-bottom: 3px;
  font-size: 13px;
}

.loc {
  font-weight: 700;
  color: var(--sys-text);
}

.cell {
  color: var(--sys-text);
  white-space: nowrap;
}

.event-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 4px 0;
  padding: 5px 8px;
  background: rgba(200, 90, 63, 0.14);
  border: 1px solid rgba(200, 90, 63, 0.45);
  border-radius: 8px;
  font-size: 12px;
}

.warn {
  color: #e4936a;
  font-weight: 700;
}

.hero-row {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 6px 0;
  padding: 8px 10px;
  background: var(--sys-panel);
  border: 1px solid rgba(205, 155, 90, 0.3);
  border-radius: 10px;
}

.hero-id {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.hero-name {
  font-size: 16px;
  font-weight: 800;
  color: var(--sys-text);
}

.hero-rank {
  font-size: 11px;
  color: #2a1c08;
  background: var(--sys-bronze);
  padding: 1px 8px;
  border-radius: 999px;
  font-weight: 700;
}

.hero-stat {
  font-size: 12px;
  color: var(--sys-text);
}

.hero-line {
  line-height: 1.6;
}

.hero-line.dim {
  color: var(--sys-text-dim);
}

.sheji-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 10px;
  font-size: 13px;
  font-weight: 700;
}

.lv {
  color: var(--sys-gold);
  font-weight: 800;
}

.r {
  color: var(--sys-text);
}

.pts {
  color: var(--sys-gold);
  font-weight: 800;
}

.zone {
  color: var(--sys-green);
}

.zone.out {
  color: var(--sys-cinnabar);
}

.timelimit {
  color: var(--sys-cinnabar);
  font-weight: 800;
}

.xp-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
}

.xp-bar {
  flex: 1;
  height: 8px;
  background: rgba(20, 16, 9, 0.7);
  border: 1px solid rgba(205, 155, 90, 0.4);
  border-radius: 999px;
  overflow: hidden;
}

.xp-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--sys-bronze), var(--sys-gold));
  box-shadow: 0 0 8px rgba(230, 192, 122, 0.6);
  transition: width 0.3s;
}

.xp-text {
  font-size: 11px;
  color: var(--sys-text-dim);
  white-space: nowrap;
}

.xianer {
  margin-top: 8px;
  border-top: 1px dashed rgba(205, 155, 90, 0.35);
  padding-top: 8px;
}

.xianer-head {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 5px;
}

.xianer-avatar {
  font-size: 15px;
}

.xianer-name {
  font-weight: 700;
  color: var(--sys-bronze);
  font-size: 12px;
}

.xianer-bubble {
  position: relative;
  background: var(--sys-panel);
  border: 1px solid rgba(205, 155, 90, 0.35);
  border-radius: 4px 12px 12px 12px;
  padding: 8px 10px;
  color: var(--sys-text);
  font-size: 13px;
  line-height: 1.6;
  word-break: break-word;
}

.xianer-bubble::before {
  content: '';
  position: absolute;
  left: -7px;
  top: 14px;
  border-style: solid;
  border-width: 6px 8px 6px 0;
  border-color: transparent var(--sys-panel) transparent transparent;
  filter: drop-shadow(-1px 0 0 rgba(205, 155, 90, 0.35));
}
