
.sec-sub {
  color: var(--sys-bronze);
  font-size: 12px;
  margin: 4px 0 2px;
}

.row-card {
  background: var(--sys-panel);
  border: 1px solid rgba(205, 155, 90, 0.28);
  border-radius: 8px;
  padding: 6px 10px;
  margin-bottom: 5px;
}

.row-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
}

.row-name {
  font-weight: 700;
  color: var(--sys-text);
}

.row-tag {
  font-size: 11px;
  color: var(--sys-gold);
  white-space: nowrap;
}

.row-sub {
  color: var(--sys-text-dim);
  font-size: 12px;
  margin-top: 1px;
}
