
.points {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: linear-gradient(90deg, rgba(230, 192, 122, 0.14), rgba(205, 155, 90, 0.08));
  border: 1px solid rgba(230, 192, 122, 0.5);
  border-radius: 10px;
  padding: 8px 12px;
}

.points-label {
  font-weight: 700;
  color: var(--sys-gold);
}

.points-value {
  font-size: 20px;
  font-weight: 800;
  color: var(--sys-gold);
  text-shadow: 0 0 10px rgba(230, 192, 122, 0.7);
}

.shop-row {
  background: var(--sys-panel);
  border: 1px solid rgba(205, 155, 90, 0.3);
  border-radius: 10px;
  padding: 8px 10px;
  margin-bottom: 6px;
}

.shop-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 3px;
}

.shop-name {
  font-weight: 700;
  color: var(--sys-text);
}

.shop-tier {
  font-size: 11px;
  padding: 0 6px;
  border-radius: 4px;
  white-space: nowrap;
}

.tier-spring {
  color: var(--sys-green);
  border: 1px solid var(--sys-green);
}

.tier-modern {
  color: var(--sys-bronze);
  border: 1px solid var(--sys-bronze);
}

.tier-contemporary {
  color: var(--sys-cinnabar);
  border: 1px solid var(--sys-cinnabar);
}

.shop-quantity {
  color: var(--sys-gold);
  font-size: 12px;
}

.shop-reason {
  color: var(--sys-text-dim);
  font-size: 12px;
  margin-top: 2px;
}

.shop-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 4px;
}

.shop-price {
  color: var(--sys-gold);
  font-weight: 700;
  font-size: 13px;
}

.buy-btn {
  background: linear-gradient(90deg, var(--sys-bronze), var(--sys-gold));
  color: #2a1c08;
  border: none;
  border-radius: 999px;
  padding: 3px 16px;
  font-family: inherit;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  transition: filter 0.15s;
}

.buy-btn:hover:not(:disabled) {
  filter: brightness(1.12);
}

.buy-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.stock-row {
  display: flex;
  align-items: center;
  gap: 8px;
  border-bottom: 1px dashed rgba(205, 155, 90, 0.18);
  padding: 4px 0;
  font-size: 13px;
}

.stock-name {
  flex: 1;
  color: var(--sys-text);
}

.stock-tier {
  font-size: 11px;
  padding: 0 6px;
  border-radius: 4px;
  white-space: nowrap;
}

.stock-qty {
  color: var(--sys-gold);
  font-weight: 700;
}
